# -*- coding: utf-8 -*-
from pathlib import Path
R=Path(__file__).resolve().parent

def start(slug,title):
 return f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Unfold 구조 시안</title><meta name="description" content="원하는 펫과 3D(GLB) 지원을 소개하는 Unfold 판매 웹 구조 시안"><link rel="icon" href="./assets/app-icon.png"><link rel="stylesheet" href="./shared.css"><link rel="stylesheet" href="./{slug}.css"></head><body class="{slug}"><a href="#main" class="skip">본문으로 건너뛰기</a>'''
def logo():
 return '<a class="brand" href="#top" aria-label="Unfold 처음으로"><img src="./assets/logo-lilac.svg" alt="Unfold" width="1162" height="320"></a>'
def pet(animated=False):
 return f'<img class="pet" src="./assets/{"pet-stretch.webp" if animated else "pet-rest.png"}" alt="고양이 Mochi" width="256" height="256">'
def menu_links():
 return '<a href="#formats">나만의 펫</a><a href="#screens">앱 화면</a><button type="button" data-buy>구매 안내 <span aria-hidden="true">↗</span></button>'
def menu_toggle():
 return '<button class="menu-toggle" type="button" aria-controls="nav-links" aria-expanded="false" aria-label="메뉴 열기"><span></span><span></span></button>'
def gallery(theme='oat',kind='tabs'):
 return f'''<div class="gallery" data-gallery data-theme="{theme}" data-current="0"><div class="screen-tabs" role="group" aria-label="실제 앱 화면 선택"><button type="button" data-shot="0" aria-pressed="true">타이머</button><button type="button" data-shot="1" aria-pressed="false">휴식 기록</button><button type="button" data-shot="2" aria-pressed="false">휴식 알림</button></div><figure class="screen-frame"><img src="./assets/{theme}-home.png" width="1120" height="800" alt="Unfold 타이머 실제 앱 화면" data-screen></figure><div class="screen-meta"><span data-shot-title aria-live="polite">타이머</span><span class="screen-source">실제 앱 화면 · Beta v1.1.3 개발본</span><div class="screen-arrows"><button type="button" data-prev aria-label="이전 앱 화면">←</button><button type="button" data-next aria-label="다음 앱 화면">→</button></div></div></div>'''
def price_body():
 return '<p class="price-label">테스트 기준가 · 세금 별도</p><p class="price">4,900<span>원</span></p><button class="button" type="button" data-buy>구매 안내 보기 <span aria-hidden="true">↗</span></button><p class="purchase-note">정식 판매 전 · 실제 청구 없음<br>Beta는 이용 코드를 받은 테스터가 사용할 수 있습니다.</p>'
def end():
 return '''<footer class="footer"><a href="./index.html">네 가지 구조 비교</a><span>© 2026 Unfold · 디자인 시안</span><span>Windows 10 이상 · macOS 13 이상</span></footer><dialog aria-labelledby="dialog-title" class="purchase-dialog"><button type="button" class="dialog-close" aria-label="구매 안내 닫기">×</button><h2 id="dialog-title">Beta 이용 안내</h2><p>현재 공개 버전은 Beta v1.1.2입니다. Google 계정으로 로그인하고 발급받은 이용 코드를 앱에 등록해 사용합니다.</p><p>4,900원은 세금 별도 테스트 기준가입니다. 테스트 결제는 실제 청구되지 않으며 앱 이용 권한을 제공하지 않습니다.</p><a class="button" href="https://unfoldpet.dokhustudio.com/#install" target="_blank" rel="noopener">공식 Beta 다운로드 ↗</a><p class="purchase-note">이 페이지는 디자인 시안입니다. 결제를 진행하지 않습니다.</p></dialog><script type="module" src="./interactions.js"></script></body></html>'''
def ticker():
 return '<div class="ticker" aria-label="지원하는 펫 파일 형식"><div><span>YOUR FILE. YOUR PET. &nbsp; 이미지 · GIF · MP4 · 3D(GLB) &nbsp;</span><span aria-hidden="true">YOUR FILE. YOUR PET. &nbsp; 이미지 · GIF · MP4 · 3D(GLB) &nbsp;</span></div></div>'
def glb_art():
 return '''<svg class="glb-art" viewBox="0 0 320 280" fill="none" aria-hidden="true"><path d="M160 24 274 86v128l-114 62L46 214V86L160 24Z" stroke="currentColor"/><path d="m46 86 114 66 114-66M160 152v124M160 24v128m-114 62 114-62 114 62" stroke="currentColor"/><path d="m74 102 86-48 87 48v96l-87 47-86-47v-96Z" stroke="currentColor" opacity=".3"/></svg>'''
magazine=start('magazine','Field journal')+f'''<header class="masthead" id="top"><div class="masthead-main">{logo()}<p>A DAILY LITTLE PAUSE</p><span>데스크톱을 위한 작은 쉼</span>{menu_toggle()}</div><nav class="masthead-nav" id="nav-links" aria-label="주요 메뉴">{menu_links()}</nav></header><main id="main"><section class="journal-cover" aria-labelledby="journal-title"><div class="cover-column cover-title"><p class="eyebrow">Make room for a little friend</p><h1 class="max-w-6xl" id="journal-title">A pet.<br>A pause.<br>Your day.</h1><div class="journal-intro"><h2>내가 고른 펫과,<br>잠깐 쉬어가세요.</h2><p>이미지·영상부터 3D(GLB)까지.</p><a class="text-link" href="#formats">어떤 펫을 넣을 수 있나요? <span aria-hidden="true">↓</span></a></div></div><figure class="cover-column cover-pet"><div class="pet-cutout">{pet(True)}</div><figcaption>좋아하는 펫을<br>내 화면 곁에.</figcaption><span class="cover-rule" aria-hidden="true"></span></figure><div class="cover-column cover-app"><p class="eyebrow">The little pause, in practice</p><figure><img src="./assets/oat-home.png" width="1120" height="800" alt="Unfold 타이머 실제 앱 화면"></figure><div class="cover-app-bottom"><p>펫이 알려 주는<br>쉬어 갈 시간.</p><a href="#screens" class="round-link" aria-label="실제 앱 화면 보기">↗</a></div><span class="screen-source">실제 앱 화면 · Beta v1.1.3 개발본</span></div></section>{ticker()}<section class="journal-spread section" id="formats"><aside class="spread-heading" data-pin><p class="eyebrow">Bring your own</p><h2 data-scrub>내 파일이,<br>나만의 펫으로.</h2><a class="text-link" href="#screens">앱 화면 살펴보기 ↓</a></aside><div class="journal-formats dense"><article class="journal-file"><p>이미지</p><strong>.png</strong>{pet()}<span>내가 좋아하는 그림</span></article><article class="journal-file"><p>움직이는 펫</p><strong>.gif<br>.mp4</strong><div class="frame-lines" aria-hidden="true"><span></span><span></span><span></span></div><span>움직임도 그대로</span></article><article class="journal-glb"><div><p>3D(GLB)</p><h3>내 3D 모델도,<br>펫으로.</h3></div>{glb_art()}</article></div></section><section class="journal-screen section" id="screens"><div class="journal-screen-title"><p class="eyebrow">A closer look</p><h2>작은 쉼을<br>펴 봅니다.</h2></div>{gallery()}</section><section class="journal-purchase section"><div><p class="eyebrow">A companion for your desktop</p><h2>다음 휴식은,<br>좋아하는 펫과.</h2></div><div>{price_body()}</div></section></main>'''+end()
# The specimen page uses a reading rail and the actual app screen as its first visual.
canvas=start('canvas','App canvas')+f'''<header class="canvas-header" id="top">{logo()}<span>데스크톱 휴식 알림 펫</span>{menu_toggle()}</header><nav class="canvas-rail" id="nav-links" aria-label="주요 메뉴"><a href="#screens" class="rail-item"><span aria-hidden="true">▣</span>앱 화면</a><a href="#formats" class="rail-item"><span aria-hidden="true">◇</span>나만의 펫</a><button class="rail-item" type="button" data-buy><span aria-hidden="true">↗</span>구매 안내</button><a href="./index.html" class="rail-back">시안 비교</a></nav><main id="main" class="canvas-main"><section class="canvas-workspace" id="screens"><div class="workspace-topline"><p class="eyebrow">Unfold, on your desktop</p><span>실제 앱을 살펴보세요</span></div><div class="canvas-layout"><div class="canvas-stage"><div class="window-chrome" aria-hidden="true"><span></span><span></span><span></span><p>Unfold / desktop</p></div>{gallery()}</div><aside class="canvas-details"><p class="eyebrow">A little company</p><h1 class="max-w-6xl">내 화면 곁에,<br>내가 고른 펫.</h1><div class="canvas-pet">{pet()}</div><p class="canvas-formats">이미지 · GIF · MP4<br><strong>3D(GLB)도 함께.</strong></p><div class="canvas-price">{price_body()}</div></aside></div></section><section class="canvas-files section" id="formats"><div class="canvas-files-title" data-pin><h2 data-scrub>내가 고른 펫을,<br>내 데스크톱에.</h2><p>이미지·영상·3D(GLB)</p></div><div class="canvas-file-deck dense"><article class="canvas-file"><span class="file-extension">.png</span>{pet()}<h3>좋아하는 그림</h3></article><article class="canvas-file"><span class="file-extension">.gif / .mp4</span><img src="./assets/pet-stretch.webp" width="256" height="256" alt="고양이의 움직임"><h3>움직이는 펫</h3></article><article class="canvas-file"><span class="file-extension">.glb</span>{glb_art()}<h3>내 3D 모델</h3></article></div></section>{ticker()}<section class="canvas-pause section"><div><p class="eyebrow">Time for a little pause</p><h2>쉬어 갈 때는,<br>펫이 알려줘요.</h2></div><figure><img src="./assets/oat-speech.png" width="524" height="196" alt="현재 앱의 휴식 알림"></figure></section><section class="canvas-end"><p>내 데스크톱에 작은 동료를.</p><button class="button" type="button" data-buy>Beta 이용 안내 ↗</button></section></main>'''+end()
journey=start('journey','Pause journey')+f'''<header class="journey-header" id="top">{logo()}<nav id="nav-links" aria-label="주요 메뉴"><a href="#journey">펫과 함께</a><a href="#formats">지원 형식</a><button type="button" data-buy>구매 안내 ↗</button></nav>{menu_toggle()}</header><main id="main"><section class="journey" id="journey"><div class="journey-stage"><div class="journey-window"><div class="journey-track"><article class="journey-panel journey-intro"><div class="journey-copy"><p class="eyebrow">A little detour in your day</p><h1 class="max-w-6xl">쉬어 갈 시간,<br>좋아하는 펫과.</h1><p class="journey-format-line">이미지·영상·3D(GLB)</p><button class="text-link" type="button" data-journey-next>다음 장면 보기 <span aria-hidden="true">→</span></button></div><div class="journey-pet-stage">{pet(True)}<p>원하는 펫을<br>내 화면 곁에.</p></div><span class="panel-word" aria-hidden="true">PAUSE.</span></article><article class="journey-panel journey-app" id="screens"><div><p class="eyebrow">Your own rhythm</p><h2>일하다.</h2></div><figure><img src="./assets/oat-home.png" width="1120" height="800" alt="Unfold 타이머 실제 앱 화면" data-scale><figcaption>실제 앱 화면 · Beta v1.1.3 개발본</figcaption></figure></article><article class="journey-panel journey-break"><div><p class="eyebrow">A moment to breathe</p><h2>쉬어가다.</h2></div><figure><img src="./assets/oat-speech.png" width="524" height="196" alt="현재 앱의 휴식 알림" data-scale><figcaption>실제 앱의 휴식 알림</figcaption></figure></article><article class="journey-panel journey-record"><div><p class="eyebrow">The little moments</p><h2>돌아보다.</h2></div><figure><img src="./assets/oat-review.png" width="1120" height="800" alt="현재 앱의 휴식 기록" data-scale><figcaption>실제 앱 화면 · Beta v1.1.3 개발본</figcaption></figure></article></div></div><div class="journey-controls"><div class="journey-progress" role="group" aria-label="이야기 장면 선택"><button type="button" data-scene="0" aria-pressed="true">내 펫</button><button type="button" data-scene="1" aria-pressed="false">일하다</button><button type="button" data-scene="2" aria-pressed="false">쉬어가다</button><button type="button" data-scene="3" aria-pressed="false">돌아보다</button></div><div class="journey-arrow-group"><button type="button" data-journey-prev aria-label="이전 장면">←</button><button type="button" data-journey-next aria-label="다음 장면">→</button></div><span class="journey-hint">스크롤로 이어지는 작은 쉼</span></div></div></section><section class="journey-formats section" id="formats"><div><p class="eyebrow">Choose your own companion</p><h2>그림이어도,<br>움직여도,<br>3D여도.</h2></div><div class="journey-format-list"><details open><summary>이미지</summary><div>{pet()}<strong>내가 좋아하는 그림.</strong></div></details><details><summary>GIF · MP4</summary><div><img src="./assets/pet-stretch.webp" width="256" height="256" alt="움직이는 고양이"><strong>움직임도 함께.</strong></div></details><details><summary>3D(GLB)</summary><div>{glb_art()}<strong>내 3D 모델도, 펫으로.</strong></div></details></div></section><section class="journey-purchase section"><div><p class="eyebrow">Take your next pause</p><h2>좋아하는 펫과,<br>다음 장면으로.</h2></div><div>{price_body()}</div></section></main>'''+end()
