catalog=start('catalog','Your pet library')+f'''<header class="catalog-header" id="top">{logo()}<nav id="nav-links" aria-label="주요 메뉴"><a href="#formats">지원하는 형식</a><a href="#screens">앱 화면</a><button type="button" data-buy>Beta 이용 안내 ↗</button></nav>{menu_toggle()}</header><main id="main"><section class="catalog-topline"><div><p class="eyebrow">Bring a pet of your own</p><h1 class="max-w-6xl">내가 고른 파일이,<br>나만의 펫으로.</h1></div><p>이미지·GIF·MP4<br>그리고 3D(GLB).</p></section><section class="catalog-layout" id="formats"><aside class="catalog-filters" data-pin><h2>지원하는 파일 형식</h2><div class="filter-list" role="group" aria-label="지원 형식 필터"><button type="button" data-filter="all" aria-pressed="true">모든 형식 <span aria-hidden="true">↗</span></button><button type="button" data-filter="image" aria-pressed="false">이미지</button><button type="button" data-filter="motion" aria-pressed="false">GIF · MP4</button><button type="button" data-filter="glb" aria-pressed="false">3D(GLB)</button></div><p class="filter-note" aria-live="polite" data-filter-status>원하는 형식을 살펴보세요.</p><a class="text-link" href="#screens">실제 앱 화면 ↓</a></aside><div class="catalog-grid dense">{format_cards}</div><aside class="catalog-purchase"><p class="eyebrow">Unfold for desktop</p><h2>내 펫과,<br>쉬어 갈 시간.</h2><div class="catalog-selected"><span>지원 형식</span><strong data-selected-format>이미지·영상·3D(GLB)</strong></div>{price_body()}<p class="catalog-os">Windows · macOS</p></aside></section>{ticker()}<section class="catalog-screens section" id="screens"><div class="catalog-screen-copy"><p class="eyebrow">On your desktop</p><h2 data-scrub>좋아하는 펫이,<br>쉬어 갈 시간을 알려줘요.</h2></div>{gallery()}</section><section class="catalog-bottom"><p>원하는 펫을 내 화면 곁에.</p><button class="button" type="button" data-buy>Beta 이용 안내 ↗</button></section></main>'''+end()
for slug,html in [('magazine',magazine),('canvas',canvas),('journey',journey),('catalog',catalog)]:
 (R/f'{slug}.html').write_text(html,encoding='utf-8')
